//particle class
class Particle{

	//constructor called when creating an instance of this class
	constructor(x,y,r,life){

		this.location = createVector(x,y) ;
		this.prevLocation = createVector(0,0) ;
		this.velocity = createVector(0, 0);
		this.alpha = this.palpha=life ;
		this.amp=3;
		this.rate = r;
		this.acceleration = createVector((noise(x)*2-1)*2, (noise(y)*2-1)*2);

	}

	//update the velociy and location of particle
	update(p){
		this.prevLocation = this.location.copy(); ;
		this.acceleration.set((noise(this.location.x)*2-1)*2, (noise(this.location.y)*2-1)*2);
		this.acceleration.setMag(0.5);
		this.velocity.add(this.acceleration);
		this.location.add(this.velocity);
		this.alpha -= this.rate ;
		this.amp-= this.rate ;
		if(this.alpha<=this.palpha*0.1 && this.palpha>10) p.push(new Particle(this.location.x, this.location.y, this.rate*0.25, this.palpha*0.5));
		this.acceleration.set(0, 0);
	}

	//show the particles
show(){
	let newLocation = createVector(this.location.x+noise(this.location.x)*2-1, this.location.y+noise(this.location.y)*2-1);
	noStroke() ;
		//fill(0,35,25, this.alpha) ;
	stroke(0);
	strokeWeight(1);
		//ellipse(this.location.x+noise(this.location.x)*2-1, this.location.y+noise(this.location.y)*2-1, this.amp);
	line(this.prevLocation.x, this.prevLocation.y, newLocation.x, newLocation.y);
	}

}

